fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();

    // Only need to check parent indices 0..floor(n/2)
    // because nodes beyond that are leaves and have no children
    let last_parent = n / 2;

    for i in 0..last_parent {
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        // Check left child if in bounds
        if left < n && a[i] > a[left] {
            return false;
        }

        // Check right child if in bounds
        if right < n && a[i] > a[right] {
            return false;
        }
    }

    // If no violation found, it is a min-heap
    true
}